  {n:'Cane table lamp',b:'Juniper Lane',i:'lamp',c:'Home',t:'new'},
  {n:'Embroidered cushion cover',b:'Juniper Lane',i:'pillow',c:'Home'}
;

// CMS-managed products are appended to the original sample catalogue.
const cmsProducts = window.ICOFYZ_CMS_DATA?.products || [];
PRODUCTS = PRODUCTS.concat(cmsProducts.map(p => ({
  n: p.name, b: p.brand || 'iCoFyz seller', i: p.icon || 'sparkle',
  c: p.category || 'Home', t: '', image: p.image || ''
})));

// Filter tabs above the products (must match the c values above)
const TABS = ['All','Home','Kitchen','Gifts'];

// "Brands we think you'll love"
//   n = name, l = location, ic = three cover icons, tags = chips, g = monogram colour
const BRANDS = [
  {n:'Northstar Ceramics',l:'Jaipur, Rajasthan',ic:['vase','mug','jar'],tags:['Handmade','Small batch'],g:'linear-gradient(135deg,#FF7A00,#E8173A)'},
  {n:'Tulsi & Rose',l:'Kochi, Kerala',ic:['bottle','candle','jar'],tags:['Natural','Vegan'],g:'linear-gradient(135deg,#C0063F,#5B12E6)'},
  {n:'Indigo Thread Co.',l:'Ahmedabad, Gujarat',ic:['shirt','tote','pillow'],tags:['Handloom','Eco-friendly'],g:'linear-gradient(135deg,#5B12E6,#1F44E0)'},
  {n:'Paper Kite',l:'Pune, Maharashtra',ic:['card','gift','ball'],tags:['Recycled paper','Women-owned'],g:'linear-gradient(135deg,#E8173A,#FF7A00)'}
];

// Your own photos (optional)
//   Every category, sub category and product shows an illustrated image by default.
//   To use a real photo instead, put the file in images/photos/ and add a line here:
//     'Exact name': 'images/photos/file-name.jpg',
//   Use only photos you own or have a licence for, without logos or brand names.
const PHOTOS = {};
const PHOTO_BY_ICON = {"vase":"data:image/webp;base64,","jar":"data:image/webp;base64,","pillow":"data:image/webp;base64,","rug":"data:image/webp;base64,","shirt":"data:image/webp;base64,","tote":"data:image/webp;base64,","bottle":"data:image/webp;base64,","candle":"data:image/webp;base64,","frame":"data:image/webp;base64,","card":"data:image/webp;base64,","book":"data:image/webp;base64,","toy":"data:image/webp;base64,","ball":"data:image/webp;base64,","jewelry":"data:image/webp;base64,","ring":"data:image/webp;base64,","watch":"data:image/webp;base64,","bag":"data:image/webp;base64,","wallet":"data:image/webp;base64,","sunglasses":"data:image/webp;base64,","lamp":"data:image/webp;base64,","bulb":"data:image/webp;base64,","plant":"data:image/webp;base64,","flower":"data:image/webp;base64,","gift":"data:image/webp;base64,","box":"data:image/webp;base64,","basket":"data:image/webp;base64,","plate":"data:image/webp;base64,","mug":"data:image/webp;base64,","glass":"data:image/webp;base64,","bowl":"data:image/webp;base64,","pan":"data:image/webp;base64,","yoga":"data:image/webp;base64,","fitness":"data:image/webp;base64,","sports":"data:image/webp;base64,","shoe":"data:image/webp;base64,","honey":"data:image/webp;base64,","chili":"data:image/webp;base64,","drop":"data:image/webp;base64,","soap":"data:image/webp;base64,","beauty":"data:image/webp;base64,","skincare":"data:image/webp;base64,","stationery":"data:image/webp;base64,","paper":"data:image/webp;base64,","kids":"data:image/webp;base64,","outdoor":"data:image/webp;base64,","travel":"data:image/webp;base64,","home":"data:image/webp;base64,","food":"data:image/webp;base64,","kitchen":"data:image/webp;base64,","decor":"data:image/webp;base64,","plantpot":"data:image/webp;base64,","storage":"data:image/webp;base64,","textile":"data:image/webp;base64,","accessory":"data:image/webp;base64,","default":"data:image/webp;base64,"};

// Assign category, subcategory, product and brand imagery by visual family.
CATEGORIES.forEach(c=>{
  const key=(c.name+' '+c.icon).toLowerCase();
  PHOTOS[c.name]=PHOTO_BY_ICON[c.icon] || (key.includes('food')?PHOTO_BY_ICON.jar:key.includes('fashion')?PHOTO_BY_ICON.shirt:PHOTO_BY_ICON.default);
  c.groups.forEach(g=>g.items.forEach(([name,icon])=>{ PHOTOS[name]=PHOTO_BY_ICON[icon] || PHOTO_BY_ICON.default; }));
});
PRODUCTS.forEach(p=>{ PHOTOS[p.n]=PHOTO_BY_ICON[p.i] || PHOTO_BY_ICON.default; });
BRANDS.forEach(b=>b.ic.forEach((icon,j)=>{ PHOTOS[b.n+j]=PHOTO_BY_ICON[icon] || PHOTO_BY_ICON.default; }));

// Apply the same premium photo system to the hero collage and feature banner.
document.querySelectorAll('.hero-art [data-icon]').forEach((el,i)=>{
  el.innerHTML=pic(el.dataset.icon,'hero-feature-'+i);
  el.classList.add('has-scene');
});
const featureBanner=document.querySelector('.banner .art');
if(featureBanner){
  featureBanner.style.backgroundImage =
    'linear-gradient(110deg,rgba(19,18,42,.28),rgba(19,18,42,.08)),' +
    'url(' + JSON.stringify(PHOTO_BY_ICON.gift) + ')';
  featureBanner.style.backgroundSize='cover';
  featureBanner.style.backgroundPosition='center';
}






